<?php
declare(strict_types=1);
require_once __DIR__ . '/auth.php';
adminRequireAuth();
$root=dirname(__DIR__);$file=$root.'/data/maktab.json';$notice='';$error='';$defaultSchool=['title'=>'Maktab','intro'=>'','image'=>'','philosophy'=>[],'values'=>[]];
function readMaktab(string $file,array $default):array{if(!is_file($file))return ['school'=>$default];$raw=file_get_contents($file);$data=is_string($raw)?json_decode($raw,true):null;if(!is_array($data)||!isset($data['school'])||!is_array($data['school']))return ['school'=>$default];foreach($default as $key=>$value){if(!array_key_exists($key,$data['school']))$data['school'][$key]=$value;if(is_array($value)&&!is_array($data['school'][$key]))$data['school'][$key]=$value;}return $data;}
function linesToArray(string $value):array{$items=[];foreach(preg_split('/\R/',$value)?:[] as $line){$line=trim($line);if($line!=='')$items[]=$line;}return $items;}
function e(mixed $value):string{return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
$data=readMaktab($file,$defaultSchool);$school=$data['school'];
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!adminVerifyCsrf((string)($_POST['csrf']??'')))throw new RuntimeException('CSRF token noto‘g‘ri yoki sessiya eskirgan.');$title=trim((string)($_POST['title']??''));$intro=trim((string)($_POST['intro']??''));$image=trim((string)($_POST['image']??''));$philosophy=linesToArray((string)($_POST['philosophy']??''));$values=linesToArray((string)($_POST['values']??''));if($title==='')throw new RuntimeException('Sarlavha bo‘sh bo‘lishi mumkin emas.');if($image!==''&&!preg_match('#^(?:https?://|/|\.\./|media/)#i',$image))throw new RuntimeException('Image path xavfsiz formatda emas.');$payload=['school'=>['title'=>$title,'intro'=>$intro,'image'=>$image,'philosophy'=>$philosophy,'values'=>$values]];$json=json_encode($payload,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($json===false||file_put_contents($file,$json.PHP_EOL,LOCK_EX)===false)throw new RuntimeException('JSON faylini saqlash amalga oshmadi.');$school=$payload['school'];$notice='Maktab kontenti saqlandi.';}catch(Throwable $ex){$error=$ex->getMessage();}}
