ass="form" method="post" autocomplete="off"><input type="hidden" name="csrf" value="<?=e(adminCsrfToken())?>"><section class="section"><div class="section-head"><h2>Identity</h2><span>01 / Core</span></div><div class="grid"><div class="field"><label for="title">Sarlavha</label><input id="title" name="title" value="<?=e($school['title'])?>" required></div><div class="field"><label for="image">Image path</label><input id="image" name="image" value="<?=e($school['image']??'')?>" placeholder="media/images/..."><small>Faqat mavjud media path yoki ishonchli URL.</small></div><div class="field wide"><label for="intro">Intro</label><textarea id="intro" name="intro" rows="5"><?=e($school['intro']??'')?></textarea></div></div></section><section class="section"><div class="section-head"><h2>Philosophy</h2><span>02 / Voice</span></div><div class="field"><label for="philosophy">Falsafa</label><textarea id="philosophy" name="philosophy" rows="8"><?=e(implode("\n",is_array($school['philosophy']??null)?$school['philosophy']:[]))?></textarea><small>Har bir qator JSON array elementiga aylanadi.</small></div></section><section class="section"><div class="section-head"><h2>Values</h2><span>03 / Principles</span></div><div class="field"><label for="values">Qadriyatlar</label><textarea id="values" name="values" rows="8"><?=e(implode("\n",is_array($school['values']??null)?$school['values']:[]))?></textarea><small>Uydirma fakt yoki statistikalar qo‘shilmadi.</small></div></section><div class="actions"><div class="hint">JSON UTF-8 · pretty-print · LOCK_EX · CSRF protected · existing school schema preserved.</div><button class="save" type="submit">SAVE CHANGES →</button></div></form><p class="footer">data/maktab.json · <?=count($school['philosophy'])?> philosophy items · <?=count($school['values'])?> values</p></main></div></body></html>